          "key": "m2-s2",
          "title": "Accurate Measuring and Managing a Practical",
          "purpose": "Learn how accurate measuring, careful checking and good organisation help you follow a recipe consistently and reduce avoidable mistakes and waste.",
          "sourceIds": [
            "PROG-2024",
            "REC-SCONES",
            "REC-TWISTS"
          ],
